with valid as (select *, concat_ws('/', segment, email) segment_email_key from customers where signup_date > to_date('2023-04-05') and city is not null) select s.id, s.name, s.email, s.country, s.signup_date, s.segment_email_key, latest.account_opened_date, latest.balance from valid s join lateral (select c.opened_date as account_opened_date, c.balance from accounts c where c.customer_id = s.id and c.opened_date <= s.signup_date order by c.opened_date desc, c.id desc limit 1) latest on true;
